 29	  const base = 10 ** exponent;
 30	  const r = x / base;
 31	  // Tolerance: log10 and the division are off by an ulp or two for values like 0.2 or 5e-7.
 32	  const tol = 1 + 1e-9;
 33	  if (r <= tol) return make(1, exponent);
 34	  if (r <= 2 * tol) return make(2, exponent);
 35	  if (r <= 5 * tol) return make(5, exponent);
 36	  return make(1, exponent + 1);
 37	}
