 56	  // Bounded: where the step is below the resolution of x, neighbouring multiples are the same double.
 57	  for (let n = 0; n < 4 && stepMultiple(i, s) < x; n++) i++;
 58	  for (let n = 0; n < 4 && stepMultiple(i - 1, s) >= x; n++) i--;
