 62	/** Index of the last multiple of the step at or below x. */
 63	export function lastIndexAtOrBelow(x: number, s: NiceStep): number {
 64	  const q = x / s.value;
 65	  let i = Math.floor(q + 1e-9 * Math.max(1, Math.abs(q)));
 66	  for (let n = 0; n < 4 && stepMultiple(i, s) > x; n++) i--;
 67	  for (let n = 0; n < 4 && stepMultiple(i + 1, s) <= x; n++) i++;
