 13	const fieldFormatters = new Map<string, Intl.DateTimeFormat>();
 14	
 15	function fieldFormatter(timeZone: string): Intl.DateTimeFormat {
 16	  let f = fieldFormatters.get(timeZone);
 17	  if (f === undefined) {
 18	    // en-US with numeric fields and h23 is the one combination whose parts are plain integers in every engine.
 19	    f = new Intl.DateTimeFormat('en-US', {
 20	      timeZone,
 21	      hourCycle: 'h23',
 22	      era: 'short',
 23	      year: 'numeric',
 24	      month: 'numeric',
 25	      day: 'numeric',
 26	      hour: 'numeric',
 27	      minute: 'numeric',
 28	      second: 'numeric',
 29	    });
 30	    fieldFormatters.set(timeZone, f);
 31	  }
 32	  return f;
 33	}
