 39	/** Epoch ms of the given UTC fields. Unlike Date.UTC, years 0–99 are not moved to the 1900s. */
 40	export function utcFields(year: number, month: number, day: number, hour = 0, minute = 0, second = 0, ms = 0): number {
 41	  const d = new Date(0);
 42	  d.setUTCFullYear(year, month, day);
 43	  d.setUTCHours(hour, minute, second, ms);
 44	  return d.getTime();
