 47	/**
 48	 * Offset of `timeZone` from UTC at `instant`, in milliseconds (positive east of Greenwich).
 49	 * Paris in winter gives 3,600,000; Los Angeles in summer gives -25,200,000.
 50	 */
 51	export function zoneOffset(timeZone: string, instant: number): number {
 52	  if (isUtc(timeZone) || !Number.isFinite(instant)) return 0;
 53	  // Offsets change on whole seconds, and Intl drops milliseconds, so compare at the whole second.
 54	  const second = Math.floor(instant / 1000) * 1000;
 55	  let year = 0, month = 0, day = 0, hour = 0, minute = 0, sec = 0;
 56	  let bc = false;
 57	  for (const part of fieldFormatter(timeZone).formatToParts(second)) {
 58	    switch (part.type) {
 59	      case 'year': year = Number(part.value); break;
 60	      case 'month': month = Number(part.value); break;
 61	      case 'day': day = Number(part.value); break;
 62	      // Some older engines write midnight as 24 even with h23.
 63	      case 'hour': hour = Number(part.value) % 24; break;
 64	      case 'minute': minute = Number(part.value); break;
 65	      case 'second': sec = Number(part.value); break;
 66	      case 'era': bc = part.value === 'BC' || part.value === 'B'; break;
 67	      default: break;
 68	    }
 69	  }
 70	  if (bc) year = 1 - year;
 71	  return utcFields(year, month - 1, day, hour, minute, sec) - second;
