 79	/**
 80	 * Every instant at which the zone's clocks show `wall`, ascending: none in a daylight-saving gap,
 81	 * two in a fold, one otherwise.
 82	 */
 83	export function wallToInstants(timeZone: string, wall: number): number[] {
 84	  if (isUtc(timeZone)) return [wall];
 85	  // The offsets a day either side are the offsets on each side of any transition near this wall time
 86	  // (zones do not change offset twice within two days).
 87	  const before = zoneOffset(timeZone, wall - DAY);
 88	  const after = zoneOffset(timeZone, wall + DAY);
 89	  const out: number[] = [];
 90	  const tryOffset = (offset: number): void => {
 91	    const t = wall - offset;
 92	    if (zoneOffset(timeZone, t) === offset && !out.includes(t)) out.push(t);
 93	  };
 94	  tryOffset(before);
 95	  if (after !== before) tryOffset(after);
 96	  if (out.length === 0 && after === before) {
 97	    // Same offset on both sides but no match: the offset changed and changed back within the window.
 98	    // Fall back to the offset at the first guess, which is right everywhere except inside that change.
 99	    const guess = wall - before;
100	    tryOffset(zoneOffset(timeZone, guess));
101	  }
102	  return out.sort((a, b) => a - b);
103	}
