107	/**
108	 * The instant at which the zone's clocks show `wall`.
109	 *  - In a fold, 'compatible' and 'earlier' give the first occurrence, 'later' the second.
110	 *  - In a gap, 'compatible' and 'later' move forward by the length of the gap (02:30 on a spring-forward
111	 *    night in Los Angeles gives 03:30 PDT), 'earlier' moves back (01:30 PST). This is what JavaScript
112	 *    Date and Temporal do.
113	 */
114	export function wallToInstant(timeZone: string, wall: number, disambiguation: Disambiguation = 'compatible'): number {
115	  const found = wallToInstants(timeZone, wall);
116	  if (found.length === 1) return found[0] as number;
117	  if (found.length > 1) return disambiguation === 'later' ? (found[found.length - 1] as number) : (found[0] as number);
