119	  const after = zoneOffset(timeZone, wall + DAY);
120	  // In a gap the offset grows (before < after). Reading the wall time with the earlier offset lands after
121	  // the transition, with the later offset before it.
122	  return disambiguation === 'earlier' ? wall - after : wall - before;
123	}
