 83	/**
 84	 * Calendar-aware tick sets, densest first. Positions are instants (epoch ms) on natural boundaries of the
 85	 * axis zone: day and coarser ticks fall on local midnight, so a "day" may be 23 or 25 hours long.
 86	 */
 87	export function timeTickCandidates(domain: readonly [number, number], options: TimeTickOptions): TickCandidates {
 88	  const lo = Math.min(domain[0], domain[1]);
 89	  const hi = Math.max(domain[0], domain[1]);
 90	  if (!Number.isFinite(lo) || !Number.isFinite(hi)) return [];
 91	  const zone = axisZone(options);
 92	  const finest = UNIT_ORDER.indexOf(finestUnit(options));
 93	  const span = hi - lo;
 94	
 95	  const sets: Tick[][] = [];
 96	  const consider = (interval: Interval): boolean => {
 97	    if (UNIT_ORDER.indexOf(interval.unit) < finest) return true;
 98	    // Skip intervals that would obviously give far too many ticks, before paying for generation.
 99	    if (span / interval.approx > MAX_TICKS + 2) return true;
100	    const values = boundaries(interval, lo, hi, zone, options.locale);
101	    if (values.length >= 1 && values.length <= MAX_TICKS) pushCandidate(sets, label(values, interval.unit, zone, options));
102	    // Go on while there is a tick: a coarser interval with as many ticks replaces the finer set, so a lone
103	    // tick ends up on the roundest boundary in the domain (midnight rather than 00:00:00.000).
104	    return values.length > 0;
105	  };
106	
107	  for (const interval of SUB_YEAR) if (!consider(interval)) return finish(sets, lo, zone, options);
108	  // Years: 1, 2, 5, 10, 20, 50, … until a single tick or none remains.
109	  for (let k = 0; k < 9; k++) {
110	    for (const m of [1, 2, 5]) {
111	      if (!consider(iv('year', m * 10 ** k))) return finish(sets, lo, zone, options);
112	    }
113	  }
114	  return finish(sets, lo, zone, options);
115	}
