136	/** Instants in [lo, hi] on the interval's boundaries in `zone`, ascending, without duplicates. */
137	function boundaries(interval: Interval, lo: number, hi: number, zone: string, locale: string): number[] {
138	  if (interval.unit === 'millisecond') {
139	    // Zone offsets are whole seconds, so millisecond boundaries are the same in every zone.
140	    const out: number[] = [];
141	    for (let t = Math.ceil(lo / interval.n) * interval.n; t <= hi; t += interval.n) out.push(t);
142	    return out;
143	  }
144	  if (isFixed(interval.unit)) return clockBoundaries(interval.n * UNIT_MS[interval.unit], lo, hi, zone);
145	  // Wall time of an instant moves back by at most the size of a fold (two hours in any zone in use), so a
146	  // three-hour margin covers every boundary whose instant lies in [lo, hi]. Day and coarser units have at
147	  // most one boundary in the margin, so it costs nothing.
148	  const wallLo = instantToWall(zone, lo) - 3 * HOUR;
149	  const wallHi = instantToWall(zone, hi) + 3 * HOUR;
150	  const out: number[] = [];
151	  for (const w of wallBoundaries(interval, wallLo, wallHi, locale)) {
152	    // Midnight inside a gap (zones that change at 00:00) moves to the first instant of that day.
153	    const t = wallToInstant(zone, w, 'compatible');
154	    if (t >= lo && t <= hi) out.push(t);
