162	 * constant offset that is plain arithmetic, so the domain is cut at its offset change, if any. A clock time
163	 * that happens twice (fold) gives two ticks; one that never happens (gap) gives none.
164	 */
165	function clockBoundaries(size: number, lo: number, hi: number, zone: string): number[] {
166	  const out: number[] = [];
167	  const push = (from: number, to: number, offset: number): void => {
168	    for (let t = Math.ceil((from + offset) / size) * size - offset; t <= to; t += size) out.push(t);
169	  };
170	  const offLo = zoneOffset(zone, lo);
171	  const offHi = zoneOffset(zone, hi);
172	  if (offLo === offHi) {
173	    // Clock ticks are only asked for spans of a few days at most, and no zone changes its offset twice
174	    // and back within that.
175	    push(lo, hi, offLo);
176	    return out;
177	  }
178	  const change = firstInstantWithOffset(zone, lo, hi, offHi);
179	  push(lo, change - 1, offLo);
180	  push(change, hi, offHi);
181	  return out;
182	}
