187	  let b = Math.ceil(hi / SECOND); // offset is `offset` here
188	  while (b - a > 1) {
189	    const m = Math.floor((a + b) / 2);
190	    if (zoneOffset(zone, m * SECOND) === offset) b = m;
191	    else a = m;
192	  }
193	  return Math.max(b * SECOND, lo);
194	}
