196	/** Wall values (local fields read as UTC) on the interval's boundaries in [wallLo, wallHi]. */
197	function wallBoundaries(interval: Interval, wallLo: number, wallHi: number, locale: string): number[] {
198	  const out: number[] = [];
199	  const { unit, n } = interval;
200	  if (unit === 'day') {
201	    // Days count from 1970-01-01, which keeps 2-day ticks evenly spaced across month ends.
202	    const size = n * UNIT_MS[unit];
203	    for (let w = Math.ceil(wallLo / size) * size; w <= wallHi; w += size) out.push(w);
204	    return out;
205	  }
206	  if (unit === 'week') {
207	    const first = weekStart(locale);
208	    let day = Math.ceil(wallLo / DAY);
209	    // 1970-01-01 was a Thursday (weekday 4, Sunday = 0).
210	    while ((((day + 4) % 7) + 7) % 7 !== first) day++;
211	    for (let w = day * DAY; w <= wallHi; w += 7 * DAY) out.push(w);
212	    return out;
213	  }
214	  const start = new Date(wallLo);
215	  if (unit === 'month') {
216	    let y = start.getUTCFullYear();
217	    let m = start.getUTCMonth() - (start.getUTCMonth() % n);
218	    for (;;) {
219	      const w = utcFields(y, m, 1);
220	      if (w > wallHi) break;
221	      if (w >= wallLo) out.push(w);
222	      m += n;
223	      if (m >= 12) { y += 1; m -= 12; }
224	    }
225	    return out;
226	  }
227	  // year
228	  const y0 = start.getUTCFullYear();
229	  for (let y = y0 - (((y0 % n) + n) % n); ; y += n) {
230	    const w = utcFields(y, 0, 1);
231	    if (w > wallHi) break;
232	    if (w >= wallLo) out.push(w);
